export const DEPARTMENTS: Department[] = rawDepartments.map((department) => DepartmentSchema.parse(department))
export const MASTER_ROSTER_CARDS: MasterRosterCard[] = rawCards.map((card) => MasterRosterCardSchema.parse(card))
export const DEPARTMENTS_BY_ID = new Map(DEPARTMENTS.map((department) => [department.id, department]))
export const DEPARTMENTS_BY_SLUG = new Map(DEPARTMENTS.map((department) => [department.slug, department]))
export function getDepartmentById(id: number): Department {
  const department = DEPARTMENTS_BY_ID.get(id)
  if (!department) throw new Error(`Unknown MiseOS department: ${id}`)
  return department
}
export function masterRosterCountsByDepartment(): Map<string, number> {
  const counts = new Map<string, number>()
  for (const card of MASTER_ROSTER_CARDS) counts.set(card.departmentSlug, (counts.get(card.departmentSlug) ?? 0) + 1)
  return counts
}
